enum MercuryType {
    // Add the fonts to the target and Info.plist (UIAppFonts); fall back to system faces otherwise.
    static func display(_ size: CGFloat) -> Font { .custom("Manrope", size: size).weight(.semibold) }
    static func body(_ size: CGFloat = 17) -> Font { .custom("Manrope", size: size) }
    static func mono(_ size: CGFloat = 13) -> Font { .custom("DM Mono", size: size) }
}

enum MercuryRadius {
    static let control: CGFloat = 8
    static let card: CGFloat = 16
}

struct PrimaryButtonStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .font(MercuryType.body(16).weight(.medium))
            .frame(maxWidth: .infinity, minHeight: 48)
            .background(Color.brandButton.opacity(configuration.isPressed ? 0.85 : 1))
            .foregroundStyle(Color.brandOnButton)
            .clipShape(RoundedRectangle(cornerRadius: MercuryRadius.control, style: .continuous))
    }
}
